<script lang="ts">
  import RunnerReference from '@/pages/competitive/RunnerReference.svelte';
  import Button from '@/components/Button.svelte';
  import {promptSpurtRate} from './report-telemetry';
  import {reportNumber as n,reportMean,type ReportDiagnostic} from './simulation-report';
  import {simulatorResults} from './simulator-results';
  import type {MonteCarloResult} from './simulator-repository';
  import type {SimulatorUma} from './simulator-uma';
  import LazyEChartsSurface from '@/components/charts/LazyEChartsSurface.svelte';
  import {distributionChart} from './distribution-chart';
  import {runnerColor} from './simulation-report';
  import {theme} from '@/stores/theme';
  let {result,umas,selected,metrics,kind,onselect,onreplay}:{result:MonteCarloResult;umas:SimulatorUma[];selected:number[];metrics:ReturnType<typeof simulatorResults>;kind:'behaviour'|'stamina';onselect:(source:number)=>void;onreplay:(index:number)=>void}=$props();
  let detailsOpen=$state(false),runnerOpen=$state<Record<number,boolean>>({}),pages=$state<Record<number,number>>({});
  const diagnostics=(s:number)=>result.report?.runners.find(r=>r.source_input_index===s)?.diagnostics??[];
  const avg=(s:number,key:keyof ReportDiagnostic)=>reportMean(diagnostics(s).map(d=>typeof d[key]==='number'?d[key] as number:undefined));
  const labels=$derived(kind==='behaviour'?['Start delay','Dash ends','Mid / late place','Blocked','Rushed','Downhill','Spot / duel']:['Full spurt','Reduced / below min. / no plan','Delayed spurt','First-check HP margin','Exhausted','Finish HP','Spurt begins','To spurt speed','Prompt full spurt']);
  const visible=$derived(kind==='behaviour'?[0,3,2]:[0,8,4,3]);
  function histogram(metric:string) {
    const rows=selected.map(source=>({source,values:metric==='finish_hp'?(result.final_hp??[]).map(r=>r[source]!).filter(Number.isFinite):diagnostics(source).map(d=>d[metric as keyof ReportDiagnostic]).filter((v):v is number=>typeof v==='number'&&Number.isFinite(v))}));
    const values=rows.flatMap(r=>r.values),min=Math.min(0,...values),max=Math.max(min+1,...values),bins=24;
    return distributionChart(rows.map(row=>{const counts=Array<number>(bins).fill(0);row.values.forEach(v=>counts[Math.min(bins-1,Math.floor((v-min)/(max-min)*bins))]!++);return {name:umas[row.source]!.name+' · #'+(row.source+1),color:runnerColor(row.source),values:counts.map(c=>row.values.length?c/row.values.length*100:0),mean:reportMean(row.values)};}),min,max,metric==='spurt_start_m'?'m':metric==='finish_hp'?'HP':'s',$theme==='dark');
  }
  function values(source:number) {
    const row=metrics.find(r=>r.source===source)!;
    if(kind==='behaviour')return [n(avg(source,'start_delay_seconds'),3)+' s',n(avg(source,'start_dash_end_seconds'))+' s',n(avg(source,'mid_place'))+' / '+n(avg(source,'late_place')),n(avg(source,'blocked_seconds'))+' s',n(avg(source,'rushed_seconds'))+' s',n(avg(source,'downhill_seconds'))+' s',n(avg(source,'spot_struggle_seconds'))+' / '+n(avg(source,'duel_seconds'))+' s'];
    const margin=reportMean(result.check_hp?.map((r,i)=>r[source]?.[0]!=null&&result.full_spurt_need_hp?.[i]?.[source]?.[0]!=null?r[source]![0]!-result.full_spurt_need_hp[i]![source]![0]!:undefined)??[]);
    return [n(row.fullSpurt,1)+'%',n((row.spurtCounts.find(s=>s.decision===2)?.count??0)/result.runs*100,1)+' / '+n((row.spurtCounts.find(s=>s.decision===4)?.count??0)/result.runs*100,1)+' / '+n((row.spurtCounts.find(s=>s.decision===8)?.count??0)/result.runs*100,1)+'%',result.report?n(diagnostics(source).filter((d,i)=>d.spurt_start_m!=null&&d.spurt_start_m>=(result.spurt_calculation_distances?.[i]?.[source]?.[0]??Infinity)+.001).length/result.runs*100,1)+'%':'—',n(margin,1)+' HP',result.report?n(diagnostics(source).filter(d=>d.exhausted_at).length/result.runs*100,1)+'%':'—',n(row.hp,1),n(avg(source,'spurt_start_m'),0)+' m',n(avg(source,'spurt_acceleration_seconds'))+' s',n(promptSpurtRate(result,source),1)+'%'];
  }
  function hp(s:number,kind:'requested'|'applied'|'wasted'|'debuff') {return reportMean(diagnostics(s).map(d=>d.hp_applications.reduce((sum,a)=>sum+(kind==='requested'?Math.max(0,a.requestedHpDelta):kind==='applied'?Math.max(0,a.appliedHpDelta):kind==='wasted'?Math.max(0,a.requestedHpDelta-a.appliedHpDelta):-Math.min(0,a.appliedHpDelta)),0)));}
  const measurements=$derived(metrics.map(row=>({...row,values:values(row.source)})));
</script>
{#if kind==='behaviour'&&!result.report}<p class="report-note">Race behaviour was not collected in this response. Update the backend and run again to collect it.</p>{:else}
  <div class="measurement-heading"><span>Runner</span>{#each visible as i}<span>{labels[i]}</span>{/each}</div>
  {#each measurements as row}<div class="measurement-row" class:highlighted={selected.includes(row.source)}><button class="runner-pick" aria-pressed={selected.includes(row.source)} onclick={()=>onselect(row.source)}><RunnerReference name={umas[row.source]!.name} cardId={umas[row.source]!.cardId} compact/></button>{#each visible as i}<span data-label={labels[i]}>{row.values[i]}</span>{/each}</div>{/each}
  <details bind:open={detailsOpen}><summary>{kind==='behaviour'?'All race modes, phase breakdowns & gate observations':'All spurt decisions, recovery & debuffs'}</summary>{#if detailsOpen}
  {#if result.report}<div class="diagnostic-plots">{#each kind==='stamina'?[['finish_hp','HP at finish'],['spurt_start_m','Spurt onset']]:[['start_delay_seconds','Start delay'],['blocked_seconds','Time blocked']] as [metric,label]}<div><h3>{label}</h3><LazyEChartsSurface option={histogram(metric!)} label={label!+' distribution for compared runners'} height={155}/></div>{/each}</div>{/if}

    <div class="detail-scroll"><table><thead><tr><th>Runner</th>{#each labels as label}<th>{label}</th>{/each}</tr></thead><tbody>{#each measurements as row}<tr><th>{umas[row.source]!.name}</th>{#each row.values as value}<td>{value}</td>{/each}</tr>{/each}</tbody></table></div>
    {#if result.report}
    {#if kind==='stamina'}<p class="report-note">Prompt full spurt also requires a chosen start no later than the first native check. Full spurt means the final native decision can afford maximum target speed (code 1). Reduced plans use code 2; below-minimum HP uses code 4; no feasible plan uses code 8. Delay compares the chosen start with the first spurt check.</p><div class="detail-scroll"><table><thead><tr><th>Runner</th><th>Requested recovery</th><th>Applied recovery</th><th>Overheal</th><th>Received HP loss</th><th>Selected / full target</th><th>Recalculations</th></tr></thead><tbody>{#each metrics as row}<tr><th>{umas[row.source]!.name}</th>{#each ['requested','applied','wasted','debuff'] as k}<td>{n(hp(row.source,k as 'requested'|'applied'|'wasted'|'debuff'),1)} HP</td>{/each}<td>{n(avg(row.source,'spurt_target_speed_mps'))} / {n(avg(row.source,'full_spurt_target_speed_mps'))} m/s</td><td>{n(reportMean(result.check_hp?.map(r=>Math.max(0,(r[row.source]?.length??1)-1))??[]))}</td></tr>{/each}</tbody></table></div>{:else}<p class="report-note">Gate values describe the submitted gate configuration, rather than a controlled gate experiment. Mid and late place are measured at each runner’s own phase entry. Mode durations use the replay’s native mode definitions.</p>{/if}
    {#each metrics as row}<details bind:open={runnerOpen[row.source]}><summary>{umas[row.source]!.name} · {result.runs} observations</summary>{#if runnerOpen[row.source]}<div class="observation-pages"><Button size="sm" variant="secondary" disabled={!(pages[row.source]??0)} onclick={()=>pages[row.source]=(pages[row.source]??0)-1}>Previous</Button><span>{(pages[row.source]??0)*25+1}–{Math.min(result.runs,((pages[row.source]??0)+1)*25)} / {result.runs}</span><Button size="sm" variant="secondary" disabled={((pages[row.source]??0)+1)*25>=result.runs} onclick={()=>pages[row.source]=(pages[row.source]??0)+1}>Next</Button></div><div class="detail-scroll"><table><thead><tr><th>Seed</th>{#if kind==='behaviour'}<th>Gate / delay</th><th>Blocked by phase (s)</th><th>Rushed / downhill (s)</th><th>Spot / duel (s)</th>{:else}<th>Spurt checks: distance / HP / required HP</th><th>HP applications: skill, time, requested → applied</th>{/if}<th>Replay</th></tr></thead><tbody>{#each diagnostics(row.source).slice((pages[row.source]??0)*25,((pages[row.source]??0)+1)*25) as d,offset}{@const i=(pages[row.source]??0)*25+offset}<tr><td>{result.seeds[i]}</td>{#if kind==='behaviour'}<td>{d.gate} / {n(d.start_delay_seconds,3)} s</td><td>{d.mode_seconds_by_phase.map(p=>n(p[0])).join(' / ')}</td><td>{n(d.rushed_seconds)} / {n(d.downhill_seconds)}</td><td>{n(d.spot_struggle_seconds)} / {n(d.duel_seconds)}</td>{:else}<td>{(result.check_hp?.[i]?.[row.source]??[]).map((v,k)=>n(result.spurt_calculation_distances?.[i]?.[row.source]?.[k],0)+' m: '+n(v,1)+' / '+n(result.full_spurt_need_hp?.[i]?.[row.source]?.[k],1)).join('; ')}</td><td>{d.hp_applications.map(a=>a.skillId+' at '+n(a.time)+' s: '+n(a.requestedHpDelta,1)+' → '+n(a.appliedHpDelta,1)+' HP').join('; ')||'None'}</td>{/if}<td><Button size="sm" variant="ghost" onclick={()=>onreplay(i)}>Open</Button></td></tr>{/each}</tbody></table></div>{/if}</details>{/each}
    {/if}
  {/if}</details>
{/if}
<style>
  .measurement-heading,.measurement-row{display:grid;grid-template-columns:minmax(145px,1.5fr) repeat(4,minmax(65px,1fr));gap:8px;align-items:center}.measurement-heading{font-size:10px;color:var(--text-secondary);padding-bottom:8px}.measurement-row{font-size:12px;padding:5px 0;border-top:1px solid var(--border-subtle)}.highlighted{background:color-mix(in srgb,var(--accent-primary) 3%,transparent)}.runner-pick{display:flex;align-items:center;background:transparent;border:0;color:inherit;padding:0;font:inherit;text-align:left;cursor:pointer;min-width:0;min-height:34px}.runner-pick:focus-visible{outline:2px solid var(--accent-primary);outline-offset:2px}
  @media(max-width:600px){.measurement-heading{display:none}.measurement-row{grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;padding:6px 0}.measurement-row>.runner-pick{grid-column:1/-1}.measurement-row>[data-label]:before{content:attr(data-label);display:block;font-size:9px;color:var(--text-secondary);margin-bottom:2px}}
  .observation-pages{display:flex;gap:12px;align-items:center;font-size:11px;padding-top:12px}
  .diagnostic-plots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:10px 0}.diagnostic-plots>div{min-width:0}@media(max-width:600px){.diagnostic-plots{grid-template-columns:1fr}}
</style>
